mapper.select:
SELECT c.kind FROM provider_attempt a
JOIN provider_channel c ON c.id = a.channel_id
WHERE a.attempt_key = #{attemptKey}

mapper.update:
UPDATE provider_channel
SET max_in_flight = #{maxInFlight}, queue_capacity = #{queueCapacity},
    queue_timeout_seconds = #{queueTimeoutSeconds}
WHERE code = #{code}
